import { test, expect } from '@playwright/test';

test.describe('Freeze First Column on Horizontal Scroll', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should freeze the first column when scrolling horizontally', async ({ page }) => {
    // Verify the table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify the first column header is visible
    const firstColumnHeader = page.getByRole('columnheader', { name: /Column 1/i });
    await expect(firstColumnHeader).toBeVisible();

    // Verify the first column data cells are visible
    const firstColumnDataCell = page.getByRole('cell', { name: /Column 1/i });
    await expect(firstColumnDataCell).toBeVisible();

    // Verify the second column header is visible
    const secondColumnHeader = page.getByRole('columnheader', { name: /Column 2/i });
    await expect(secondColumnHeader).toBeVisible();

    // Verify the second column data cells are visible
    const secondColumnDataCell = page.getByRole('cell', { name: /Column 2/i });
    await expect(secondColumnDataCell).toBeVisible();

    // Scroll horizontally to the right
    const scrollBar = page.getByRole('slider', { name: /scroll/i });
    await scrollBar.click({ position: 'center' });
    await page.waitForTimeout(50);

    // Verify the first column is frozen and visible
    await expect(firstColumnDataCell).toBeVisible();

    // Verify the second column is visible and scrollable
    await expect(secondColumnDataCell).toBeVisible();

    // Scroll horizontally to the left
    await scrollBar.click({ position: 'center' });
    await page.waitForTimeout(50);

    // Verify the first column is still frozen and visible
    await expect(firstColumnDataCell).toBeVisible();

    // Verify the second column is visible and scrollable
    await expect(secondColumnDataCell).toBeVisible();
  });

  test('should freeze the first column when scrolling vertically', async ({ page }) => {
    // Verify the table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify the first column header is visible
    const firstColumnHeader = page.getByRole('columnheader', { name: /Column 1/i });
    await expect(firstColumnHeader).toBeVisible();

    // Verify the first column data cells are visible
    const firstColumnDataCell = page.getByRole('cell', { name: /Column 1/i });
    await expect(firstColumnDataCell).toBeVisible();

    // Verify the second column header is visible
    const secondColumnHeader = page.getByRole('columnheader', { name: /Column 2/i });
    await expect(secondColumnHeader).toBeVisible();

    // Verify the second column data cells are visible
    const secondColumnDataCell = page.getByRole('cell', { name: /Column 2/i });
    await expect(secondColumnDataCell).toBeVisible();

    // Scroll vertically to the bottom
    const scrollBar = page.getByRole('slider', { name: /scroll/i });
    await scrollBar.click({ position: 'center' });
    await page.waitForTimeout(50);

    // Verify the first column is frozen and visible
    await expect(firstColumnDataCell).toBeVisible();

    // Verify the second column is visible and scrollable
    await expect(secondColumnDataCell).toBeVisible();

    // Scroll vertically to the top
    await scrollBar.click({ position: 'center' });
    await page.waitForTimeout(50);

    // Verify the first column is still frozen and visible
    await expect(firstColumnDataCell).toBeVisible();

    // Verify the second column is visible and scrollable
    await expect(secondColumnDataCell).toBeVisible();
  });
});
